const section=(title,...paragraphs)=>({title,html:paragraphs.map(p=>`<p>${p}</p>`).join('')});
const ref=(id,label='Veja a referência')=>`<a class="source-link" href="${communitySources[id].url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const entry=(model,slug,title,excerpt,category,intro,sections,codes,refs=['catalog'])=>({slug,title,description:excerpt,excerpt,category,topics:[model],image:images[model][0],imageAlt:images[model][1],intro,sections:sections.map((s,i)=>({...s,id:'passo-'+(i+1)})),kits:codes.map(c=>[model,c]),sources:refs});

export const communityPosts = [
  entry('tr4','tr4-comunidade-historias-encontros','TR4: o carro que vira assunto, amizade e encontro',
    'O que os encontros de Pajero TR4 revelam sobre pertencimento e como transformar a conversa entre donos em cuidado com o carro.', 'Comunidades',
    'Às vezes, basta estacionar uma TR4 para começar uma conversa. O assunto passa pela viagem, chega à peça difícil de identificar e termina com um convite para o próximo encontro. Esse vínculo merece espaço além da ficha técnica.',[
      section('Há sinais concretos desse vínculo','O Clube TR4 Brasília DF anunciou um encontro específico para 12 de novembro de 2026. A página apresenta troca de experiências e convivência entre entusiastas. É evidência de mobilização, embora o anúncio sozinho não confirme o público que compareceu. '+ref('tr4club','Conheça o anúncio do organizador')+'.','O interesse editorial está nas histórias: quem usa o carro todos os dias, quem viaja em família e quem está começando a conhecer o modelo. Esses perfis podem conviver no mesmo grupo sem ter as mesmas necessidades de manutenção.'),
      section('Uma boa história tem contexto','Quando alguém contar que resolveu um problema, pergunte qual era o ano, a versão e a condição encontrada. A resposta “troquei uma bucha” fica muito mais útil quando inclui a posição da peça e o diagnóstico que justificou o serviço.','Guarde a experiência como uma pergunta para a oficina. O relato de outro proprietário pode orientar a investigação, mas não descreve o estado do seu carro. Mesmo duas TR4 semelhantes podem ter históricos muito diferentes.'),
      section('Leve curiosidade, não uma lista de compras','No primeiro contato com a comunidade, apresente seu uso e escute. Pergunte sobre organização de passeios, cuidados com registros de manutenção e fontes de informação. Uma conversa respeitosa abre mais portas do que chegar divulgando produtos.','Vale criar uma pasta com notas, códigos e fotografias dos serviços já feitos. Assim, a memória da comunidade complementa a memória do veículo, em vez de substituí-la.'),
      section('Da conversa para a aplicação','Para consultar peças, comece pelo conjunto apontado na avaliação. O KIT10055 e o KIT10082 aparecem no catálogo da TR4 com descrições próprias; não devem virar uma compra automática por terem sido citados em um grupo.','Qual história fez você se apegar à sua TR4? Conte para a RochaPro e, se houver uma revisão em andamento, envie ano, versão e o código indicado pela oficina para conferir os kits abaixo.')
    ],['KIT10055','KIT10082'],['tr4club','catalog']),
  entry('tr4','primeiro-encontro-pajero-tr4','Primeiro encontro de TR4: como chegar sabendo o que perguntar',
    'Um roteiro de perguntas para entender o perfil do encontro de TR4, organizar a participação e aproveitar a troca com outros proprietários.', 'Vida com o carro',
    'Encontro em estacionamento, passeio turístico e atividade fora de estrada são programas diferentes. Antes de inscrever sua TR4, descubra qual experiência está sendo proposta. O nome do evento, sozinho, não informa terreno, duração ou estrutura de apoio.',[
      section('Converse com a organização','Peça o roteiro, o horário de encerramento e as regras de participação. Confirme se haverá deslocamento em grupo, parada para alimentação e alternativas para quem decidir voltar antes. Se for com crianças ou acompanhantes, inclua as necessidades deles nessa conversa.','O anúncio do encontro da TR4 em Brasília, em novembro de 2026, exemplifica uma proposta de convivência entre entusiastas. Ele serve como contexto cultural, não como recomendação de agenda futura. '+ref('tr4club')+'.'),
      section('Prepare perguntas que geram respostas úteis','Troque “qual é a melhor peça?” por perguntas mais concretas: qual conjunto foi avaliado, qual código foi usado, em que versão e por qual motivo? Esse formato ajuda a separar preferência pessoal de informação aplicável.','Observe também como o grupo recebe iniciantes. Explicações claras, respeito aos limites de cada participante e disposição para compartilhar referências são bons critérios para decidir se você quer voltar.'),
      section('Organize o antes e o depois','Deixe endereço, contatos e programação acessíveis. Se o carro precisa de avaliação, resolva isso com antecedência, permitindo tempo para diagnóstico e conferência das peças. A proximidade do encontro não transforma um reparo pendente em algo dispensável.','Na volta, registre as dúvidas que surgiram e os contatos autorizados a permanecer na sua agenda. Não publique imagens de outras pessoas ou placas sem combinar; a lembrança do passeio deve respeitar quem participou.'),
      section('Consulte somente o que fizer sentido para a sua revisão','No catálogo, KIT10170 e KIT10273 atendem posições diferentes na TR4 e trazem recortes de aplicação. Confira as descrições antes de pedir orçamento. A presença de um kit neste artigo não significa que ele seja necessário para participar de um encontro.','Vai preparar a TR4 para o próximo programa? Envie à RochaPro ano, versão e a indicação da oficina; consulte os kits relacionados no final da página.')
    ],['KIT10170','KIT10273'],['tr4club','catalog']),
  entry('tr4','tr4-historico-manutencao-organizado','TR4 usada: monte uma memória de manutenção que acompanha o carro',
    'Notas, datas e códigos ajudam a entender uma TR4 usada. Veja como organizar o histórico sem confundir ausência de registro com diagnóstico.', 'Organização da manutenção',
    'Uma pasta bem organizada não muda o estado de uma TR4, mas melhora muito a conversa sobre ele. Ela permite distinguir o serviço comprovado, a informação verbal e o item que ainda precisa de avaliação. Esse cuidado vale tanto para quem acabou de comprar quanto para quem guarda o carro há anos.',[
      section('Separe documento de lembrança','Comece reunindo notas de peças, ordens de serviço e registros de quilometragem. Anote quem executou cada trabalho e qual conjunto foi atendido. Uma descrição como “revisão geral” pode ser verdadeira, mas não informa quais componentes foram efetivamente inspecionados ou trocados.','Mantenha uma coluna para relatos do antigo proprietário que ainda não têm comprovante. Não descarte a informação; identifique sua origem. Também não trate uma pasta vazia como prova de defeito: ela revela falta de documentação, que a inspeção ajuda a esclarecer.'),
      section('Crie uma linha do tempo simples','Use cinco campos: data, quilometragem registrada, serviço, código da peça e documento. Se houver correção posterior, acrescente uma observação em vez de apagar a anotação original. Fotografias podem complementar o registro quando mostram etiqueta, embalagem ou peça identificada.','Guarde o arquivo em um local fácil de atualizar. Uma planilha curta e usada depois de cada serviço costuma ser mais útil do que um sistema complexo abandonado na primeira semana.'),
      section('Identifique a posição, não apenas o apelido','“Bucha do diferencial” e “bucha do câmbio” descrevem conjuntos diferentes. No cadastro RochaPro, KIT10427 corresponde à bucha central do diferencial dianteiro; KIT10426 se refere à travessa do câmbio da TR4, com aplicação descrita por período. '+ref('catalog','Confira o catálogo')+'.','Anote a descrição completa que consta no orçamento aprovado. Isso reduz a chance de reutilizar o código de um serviço anterior para uma necessidade nova, apenas porque os nomes parecem próximos.'),
      section('Use o histórico na próxima conversa','Antes de pedir peças, compartilhe com a oficina o que já foi feito e o que mudou no comportamento do carro. Depois, registre a conclusão da avaliação, inclusive quando não houver troca. A ausência de substituição também pode ser uma informação útil.','Quer organizar uma cotação? Envie ano, versão e o conjunto indicado à RochaPro. Os kits abaixo ajudam a localizar as aplicações citadas, sujeitas à conferência e disponibilidade.')
    ],['KIT10427','KIT10426']),
  entry('tr4','tr4-4x2-4x4-identificar-pecas','TR4 4x2 ou 4x4: a identificação vem antes da busca por peças',
    'Ano, versão, tração e posição do componente: organize os dados da sua Pajero TR4 antes de comparar kits e pedir uma cotação.', 'Aplicação de peças',
    'Dizer apenas “é para uma TR4” deixa perguntas importantes em aberto. A identificação do veículo e do conjunto é o primeiro passo para uma consulta útil, especialmente quando a busca mistura anúncios, experiências de outros donos e nomes abreviados de peças.',[
      section('Monte uma ficha do veículo','Registre ano de fabricação, ano-modelo, versão e configuração de tração. Use a documentação e as informações do próprio veículo para conferir os dados. Quando houver dúvida, peça ajuda ao profissional responsável pela avaliação, em vez de deduzir a configuração pela aparência.','A ficha deve acompanhar a cotação. Se a conversa passar de um atendente para outro, os dados continuam claros e não dependem de uma mensagem antiga perdida no histórico.'),
      section('Não deduza intercâmbio pelo nome','Dois anúncios que citam TR4 não comprovam que as peças sejam intercambiáveis. É preciso comparar posição, medidas, quantidade e recorte de aplicação. Da mesma forma, citar 4x2 ou 4x4 não autoriza concluir, sem documentação, que todos os componentes sejam diferentes.','O objetivo é fazer a pergunta certa para cada código. Se o cadastro não esclarecer uma variação, solicite confirmação; a lacuna não deve ser preenchida com uma suposição.'),
      section('Compare descrições completas','O KIT10082 aparece como aplicação dianteira no catálogo, enquanto o KIT10170 está associado à aplicação traseira da TR4, com período indicado. Essa diferença de posição já mostra por que uma foto isolada ou o nome do modelo não bastam. '+ref('catalog')+'.','Ao receber um orçamento, confira se a descrição responde à necessidade apontada na inspeção. Se não responder, peça a correção antes de avançar. Não há benefício em comparar preços de itens que atendem conjuntos diferentes.'),
      section('Transforme a ficha em uma consulta','Uma mensagem objetiva pode dizer: “Tenho uma TR4, ano e versão informados, e a oficina indicou a peça nesta posição. Podem conferir o código e as medidas?”. Fotografias da peça identificada podem complementar a conversa, sem substituir a avaliação presencial.','Consulte os kits abaixo e fale com a RochaPro com esses dados. A equipe poderá verificar a aplicação cadastrada e a disponibilidade para o seu pedido.')
    ],['KIT10082','KIT10170']),
  entry('tr4','tr4-dianteira-traseira-nomes-buchas','Buchas da TR4: como organizar os nomes da dianteira à traseira',
    'Estabilizadora, tensor e braço traseiro não são o mesmo conjunto. Aprenda a ler a descrição dos kits da TR4 com mais clareza.', 'Entenda o catálogo',
    'Na conversa da oficina, os nomes das peças podem vir abreviados. Na hora de comprar, essa economia de palavras atrapalha. Uma forma de organizar a informação é perguntar a qual conjunto o item pertence, em qual eixo fica e qual posição ocupa.',[
      section('Leia a descrição em camadas','Comece pelo conjunto: estabilizadora, braço, tensor ou suporte. Depois procure dianteiro ou traseiro e, quando informado, superior, inferior, central ou ponta. Só então compare ano, versão e medidas. Essa leitura evita escolher pela primeira palavra que parece familiar.','Se o orçamento trouxer apenas “buchas TR4”, peça detalhamento. O nome incompleto pode ser suficiente entre profissionais que já examinaram o carro, mas não necessariamente para quem vai separar a mercadoria.'),
      section('Três códigos, três consultas diferentes','O KIT10273 é descrito para a ponta do braço tensor dianteiro. O KIT10358 corresponde ao braço transversal traseiro e o KIT10190 ao braço traseiro, nas aplicações informadas no catálogo. Esses nomes não devem ser usados como sinônimos. '+ref('catalog','Veja as descrições por código')+'.','A lista serve para localizar os itens, não para ensinar sua instalação nem indicar que todos precisem de troca. O reparo deve seguir o diagnóstico do conjunto e a documentação adequada ao veículo.'),
      section('Use fotos como apoio','Uma imagem com a peça indicada e a orientação do conjunto ajuda a esclarecer uma dúvida de atendimento. Se houver embalagem ou código antigo, fotografe também. Não conte com a perspectiva de uma foto para determinar uma medida que precisa ser conferida tecnicamente.','Quando o produto estiver sem fotografia no catálogo, peça as informações à equipe. Ausência de imagem não autoriza escolher outro kit por semelhança visual.'),
      section('Feche a conversa com uma descrição única','Antes de confirmar a cotação, reúna código, descrição, quantidade, ano e versão em uma mesma mensagem. Essa pequena revisão reduz ambiguidades entre o que foi identificado na oficina e o que será solicitado à loja.','Está com dúvida entre os nomes? Envie a indicação do profissional à RochaPro e consulte os kits abaixo. Vamos começar pela posição correta, antes de falar em substituição.')
    ],['KIT10273','KIT10358','KIT10190']),
  entry('tr4','tr4-diario-viagens-revisoes','Diário da TR4: registre viagens sem perder a memória dos cuidados',
    'Junte as histórias da estrada aos registros da sua TR4: um diário simples ajuda a lembrar o que aconteceu e o que perguntar na revisão.', 'Histórias de estrada',
    'O álbum guarda a paisagem; o diário pode guardar o que aconteceu entre uma foto e outra. Não precisa virar uma obrigação. Algumas anotações depois de cada viagem já ajudam a lembrar o uso do carro e a preparar uma conversa mais precisa na próxima avaliação.',[
      section('Conte a viagem com dados simples','Anote destino, datas, quilometragem registrada e tipo de percurso. Acrescente as paradas marcantes e o que gostaria de fazer diferente. Se houve alteração no planejamento, registre o motivo: horário, clima, preferência dos passageiros ou condição encontrada.','Esse contexto é mais útil do que classificar toda saída como “leve” ou “pesada”. São palavras relativas, e cada pessoa pode estar pensando em uma situação diferente ao usá-las.'),
      section('Separe experiência de sintoma','Em outra parte do diário, registre somente mudanças percebidas no carro. Descreva quando aconteceram, em que condição e se voltaram a aparecer. Não é necessário atribuir uma causa. “Percebi um ruído ao passar por uma irregularidade” preserva melhor a observação do que nomear uma peça sem avaliação.','Não tente reproduzir uma situação arriscada para completar a anotação. Se o comportamento exigir atenção, procure avaliação profissional antes de continuar usando o veículo.'),
      section('Complete o registro depois da oficina','Guarde a conclusão do diagnóstico e os códigos efetivamente utilizados. O KIT10923, por exemplo, aparece no catálogo para a posição inferior do amortecedor traseiro da TR4; o KIT10170 tem outra descrição de aplicação traseira. O histórico deve conservar essa diferença. '+ref('catalog')+'.','Quando nenhum componente for substituído, registre as orientações recebidas e o que ficou para acompanhamento. Assim, a próxima consulta começa com informações, e não apenas com lembranças.'),
      section('Compartilhe a história que vale a pena','Uma boa publicação para a comunidade pode reunir a paisagem, uma descoberta do caminho e um cuidado aprendido. Não precisa transformar cada viagem em comparação de desempenho. Os detalhes do cotidiano aproximam quem está começando e quem já conhece bem o modelo.','Qual viagem merece a próxima página do diário da sua TR4? Se ela trouxe uma necessidade de manutenção identificada, consulte os kits abaixo e fale com a RochaPro para conferir a aplicação.')
    ],['KIT10923','KIT10170']),
  entry('troller','troller-clubes-pertencimento','Troller além da trilha: encontros, memória e pertencimento',
    'A cultura Troller também aparece em encontros e turismo. Veja como participar dessa conversa e preservar informações úteis sobre seu veículo.', 'Comunidades',
    'O interesse pelo Troller não começa e termina no obstáculo. Ele aparece nas histórias de viagem, nos encontros de famílias e no cuidado de conservar um veículo com o qual o dono se identifica. Esse universo rende conversas que vão muito além de acessórios.',[
      section('Comunidade também ocupa outros espaços','A programação divulgada pela Setur-RJ para um festival em fevereiro de 2025 incluiu exposição do Troller Clube RJ. O anúncio mostra a presença do grupo em um contexto turístico e cultural, sem permitir medir quantas pessoas foram atraídas especificamente pelos carros. '+ref('trollerRJ')+'.','É uma boa lembrança de que participar pode significar conversar, conhecer lugares e trocar experiências. Nem todo encontro exige um roteiro fora de estrada, e nem todo proprietário busca a mesma atividade.'),
      section('Procure um grupo compatível com seu momento','Antes de entrar em um passeio, pergunte sobre formato, organização e perfil dos participantes. Se você quer começar por uma conversa tranquila, um encontro estático pode ser uma oportunidade diferente de uma expedição.','Observe a qualidade da troca: relatos contextualizados, respeito aos iniciantes e clareza sobre regras ajudam a construir confiança. Popularidade de uma página ou quantidade de fotografias antigas não comprovam que o grupo esteja ativo hoje.'),
      section('A memória do carro também merece espaço','Guarde documentos de serviços, identificação das peças e fotos autorizadas de momentos importantes. Quando um item recebe nomes diferentes entre proprietários, o código e a posição ajudam a manter a conversa objetiva.','No catálogo RochaPro, KIT10343 se refere à aplicação de Panhard e KIT10375 ao conjunto de buchas grandes do braço tensor, com períodos definidos. São consultas diferentes, mesmo que apareçam na mesma conversa sobre suspensão. '+ref('catalog')+'.'),
      section('Transforme afinidade em cuidado bem informado','Use a comunidade para descobrir perguntas e compartilhar experiências, sem transformar um relato em diagnóstico do seu Troller. Antes de cotar peças, confirme ano, versão e a necessidade identificada pelo profissional.','Que lembrança melhor representa sua relação com o Troller? Conte à RochaPro e confira abaixo as aplicações relacionadas quando houver um reparo indicado.')
    ],['KIT10343','KIT10375'],['trollerRJ','catalog']),
  entry('troller','troller-panhard-tensor-estabilizadora','Troller: Panhard, tensor e estabilizadora no pedido de peças',
    'Três nomes que aparecem na manutenção do Troller. Organize posição, código e aplicação para evitar uma cotação com peças de conjuntos diferentes.', 'Entenda o catálogo',
    'Um pedido de “kit de suspensão do Troller” pode significar muitas coisas. Para chegar à peça correspondente ao serviço, vale descrever o conjunto com mais precisão. O objetivo não é decorar toda a mecânica do carro: é impedir que nomes diferentes se percam na conversa.',[
      section('Comece pela indicação da oficina','Peça que o orçamento identifique conjunto, posição e quantidade. Se o profissional utilizar um apelido, solicite também a descrição da peça ou uma referência que permita localizá-la. Essa informação evita depender de uma fotografia encontrada por acaso na internet.','A posição deve acompanhar o nome. “Traseira”, por exemplo, é parte importante da descrição de uma estabilizadora quando o catálogo diferencia aplicações.'),
      section('Veja como o catálogo separa as consultas','O KIT10343 está cadastrado para Panhard do Troller de 2002 a 2014. O KIT10375 se refere a quatro buchas grandes do braço tensor no período indicado. Já o KIT10363 é apresentado para a estabilizadora traseira de 2002 a 2014. '+ref('catalog')+'.','A existência desses três códigos não informa o que está desgastado no seu veículo. Ela mostra apenas que “bucha do Troller” não é uma identificação suficiente para comparar produtos.'),
      section('Não escolha pela quantidade ou aparência','Um conjunto com mais componentes não é automaticamente a melhor compra para o reparo indicado. O mesmo vale para peças que parecem semelhantes nas imagens: função, medidas e aplicação precisam coincidir com a necessidade confirmada.','Se o carro tiver alterações anteriores, informe isso à oficina e ao atendimento. Uma aplicação prevista para determinada configuração não comprova compatibilidade com um conjunto modificado.'),
      section('Revise o pedido antes de concluir','Compare o código cotado com a descrição recebida da oficina. Confira ano e versão, confirme quantidade e pergunte sobre qualquer ponto que tenha ficado implícito. A checagem final é especialmente útil quando mais de uma pessoa participa da compra.','Envie à RochaPro a indicação do serviço e os dados do seu Troller. Os três kits abaixo permitem iniciar a consulta pelo conjunto correto, com confirmação de aplicação e disponibilidade.')
    ],['KIT10343','KIT10375','KIT10363']),
  entry('troller','troller-ano-versao-aplicacao-kits','O ano do Troller importa: como ler os limites de aplicação de um kit',
    'Nem todo kit cadastrado para Troller cobre todos os anos. Entenda os recortes do catálogo antes de aproveitar a indicação de outro proprietário.', 'Aplicação de peças',
    'Um amigo usa determinada peça no Troller dele e recomenda a mesma para você. Antes de aceitar a indicação, há uma pergunta simples: os veículos e os conjuntos correspondem à mesma aplicação? O entusiasmo pelo modelo não elimina essa conferência.',[
      section('Ano de fabricação e ano-modelo não são a mesma informação','Anote os dois dados e a versão conforme a documentação. Quando o catálogo apresenta um intervalo de anos, peça confirmação sobre o enquadramento do seu carro, sobretudo perto das transições. Não tente resolver a dúvida apenas pela aparência externa.','Também registre alterações conhecidas no conjunto que será atendido. A ficha do veículo descreve sua origem, mas o profissional precisa avaliar o que está instalado atualmente.'),
      section('Um limite escrito deve ser respeitado','O KIT10363 aparece para Troller de 2002 a 2014. O KIT10428 tem descrição para amortecedor traseiro de 2004 a 2014. Esses intervalos não autorizam extrapolar a aplicação para veículos posteriores nem transformar os dois itens em equivalentes. '+ref('catalog')+'.','Quando um código não traz o ano claramente, isso também não significa “serve em todos”. Significa que a consulta precisa ser completada com a equipe e com a identificação do conjunto.'),
      section('O relato do grupo precisa de identificação','Se alguém compartilhar uma solução, pergunte qual era o ano e a versão do carro, a posição da peça e se havia modificações. Uma experiência bem descrita ajuda a formular perguntas; uma frase solta pode levar a comparar situações diferentes.','Preserve a referência do produto que foi efetivamente utilizado, mas não trate a repetição de uma indicação como prova técnica. A aplicação deve ser conferida para o seu veículo.'),
      section('Faça a cotação por código e descrição','Envie os dados completos e a indicação da oficina. Peça que a resposta registre qual código corresponde à necessidade e quais informações ainda precisam ser verificadas. Isso deixa a decisão rastreável e evita escolher por semelhança.','Consulte abaixo os kits citados e fale com a RochaPro. Se o ano ou a configuração não estiverem contemplados na descrição, solicite análise antes de considerar a compra.')
    ],['KIT10363','KIT10428']),
  entry('troller','troller-expedicao-planejamento-grupo','Expedição de Troller: as perguntas que vêm antes da bagagem',
    'Roteiro, apoio, duração e condição do veículo: organize a conversa com o grupo antes de preparar o Troller para uma viagem longa.', 'Expedição',
    'Uma expedição começa muito antes de fechar o porta-malas. O primeiro trabalho é entender o programa e descobrir se ele combina com o carro, os ocupantes e o tempo disponível. Uma lista de acessórios não responde a essas perguntas.',[
      section('Peça um roteiro que possa ser entendido','Converse sobre distâncias previstas, pernoites, abastecimento e pontos de saída do percurso. Pergunte o que acontece quando alguém precisa voltar ou quando uma passagem deixa de ser viável. O plano deve comportar mudança de decisão.','Nas regiões com grandes distâncias, inclusive em viagens que envolvem a Transamazônica, o trecho e a época precisam ser avaliados perto da partida. Um relato antigo ajuda a conhecer a experiência de alguém; não é boletim atual da estrada.'),
      section('Entenda o que está incluído no apoio','Não suponha que estar em grupo resolve qualquer imprevisto. Pergunte quais responsabilidades são da organização e quais permanecem com cada participante. Confirme canais de comunicação, encontros combinados e limites do suporte oferecido.','Compartilhe também as necessidades dos acompanhantes. Horário, alimentação, descanso e possibilidade de encurtar o programa fazem parte da escolha do roteiro, e não de um detalhe a resolver depois.'),
      section('Dê tempo à avaliação do veículo','Leve à oficina a descrição do uso previsto e o histórico do Troller. O diagnóstico pode apontar um conjunto diferente daquele que você imaginava revisar. Evite pedir uma troca genérica de buchas só porque a viagem terá terra no caminho.','No catálogo, KIT10363 e KIT10343 têm descrições para estabilizadora traseira e Panhard, respectivamente, com período de aplicação. Não são pacotes de adaptação para expedição. '+ref('catalog')+'.'),
      section('A melhor lista vem depois das respostas','Quando roteiro e avaliação estiverem claros, organize documentação, contatos, bagagem e o que foi orientado para o veículo. Revise o plano com o grupo e aceite modificar a viagem se as condições mudarem.','Está preparando o Troller e recebeu indicação de peças? Fale com a RochaPro com ano, versão e posição do componente. Confira os kits abaixo como ponto de partida para a cotação.')
    ],['KIT10363','KIT10343']),
  entry('hilux','hilux-trabalho-passeio-familia','Hilux de segunda a domingo: trabalho e passeio no mesmo histórico',
    'A Hilux pode participar de rotinas diferentes. Registre o uso real para organizar a manutenção e preparar a próxima saída em família.', 'Vida com o carro',
    'Durante a semana, compromissos e trabalho. No fim de semana, uma viagem com a família. Quando a mesma Hilux participa de rotinas diferentes, vale registrar essas mudanças para que o histórico de manutenção descreva o uso real do veículo.',[
      section('O passeio também faz parte da cultura do modelo','A Mercosul Toyota publicou em setembro de 2025 um registro do Hilux Expedition em Lages. O relato do organizador mostra uma experiência presencial com clientes, sem fornecer uma medida comparável de engajamento da comunidade. '+ref('hiluxClub')+'.','Esse tipo de encontro é um ponto de partida para conversar sobre convivência, roteiros e organização. Não implica que toda Hilux tenha o mesmo uso ou que todos os participantes precisem das mesmas peças.'),
      section('Descreva as diferenças da sua semana','Anote se predominam deslocamentos curtos, estrada, vias não pavimentadas ou períodos com o veículo parado. Registre a presença habitual de carga e acessórios, sem tentar classificar tudo por um rótulo genérico. A oficina poderá relacionar esse contexto à documentação da versão.','Para a viagem, confira o planejamento dos ocupantes e da bagagem conforme os limites do veículo. Usar a caçamba todos os dias não dispensa reorganizar o que será transportado em um passeio.'),
      section('Não transforme mudança de programa em troca automática','Ir a um encontro não exige comprar um kit por antecipação. Primeiro, entenda o percurso e verifique as necessidades reais de manutenção. Se houver reparo indicado, identifique o conjunto, a posição e a aplicação da peça.','O KIT10124 e o KIT10062 estão relacionados ao feixe de molas traseiro da Hilux no catálogo. A seleção entre códigos depende da descrição e da conferência, não do nome do passeio.'),
      section('Registre o retorno','Depois da saída, anote percurso e mudanças percebidas no carro. Complete o histórico com qualquer avaliação realizada. Essa continuidade ajuda a evitar que a manutenção da “Hilux de trabalho” e da “Hilux de passeio” pareça pertencer a dois veículos diferentes.','Vai consultar peças para uma necessidade identificada? Envie ano, versão e a indicação do serviço à RochaPro e confira os kits relacionados abaixo.')
    ],['KIT10124','KIT10062'],['hiluxClub','catalog']),
  entry('hilux','hilux-sw4-nomes-aplicacoes-diferentes','Hilux e SW4: nomes próximos não confirmam a mesma aplicação',
    'Saiba por que é preciso conferir o modelo completo na busca por buchas e como evitar misturar kits exclusivos da SW4 com peças da Hilux.', 'Aplicação de peças',
    'Resultados de busca costumam reunir Hilux e SW4 na mesma tela. Isso facilita encontrar informações, mas também pode esconder uma diferença decisiva: um produto citado para a SW4 não está automaticamente indicado para a picape Hilux.',[
      section('Escreva o modelo completo','Ao pedir uma cotação, informe claramente se o veículo é a picape Hilux ou a SW4. Acrescente ano, versão e a posição do componente. Não deixe a identificação depender da interpretação de uma foto ou de uma abreviação.','Se o orçamento veio de outra fonte, preserve o código e a descrição completos. Um título encurtado em uma mensagem pode perder justamente a informação que limita a aplicação.'),
      section('Entenda o recorte da página da Hilux','A seleção pública da RochaPro para Hilux separa os itens exclusivos da SW4. No catálogo geral, há códigos com descrições específicas para os tensores da SW4; isso não os transforma em opção para a picape. '+ref('catalog')+'.','Por outro lado, quando uma descrição menciona mais de um modelo, é preciso conferir as condições aplicáveis a cada um. Uma aplicação compartilhada deve estar documentada, e não ser presumida pela proximidade dos nomes.'),
      section('Compare o conjunto que será reparado','Comece pela indicação da oficina e só depois procure o código. Se o diagnóstico aponta o feixe de molas traseiro, não compare o orçamento com um kit de outro conjunto apenas porque o anúncio também cita Toyota.','KIT10124 e KIT10061 aparecem entre as opções para Hilux com descrições ligadas ao feixe de molas e seus componentes. A equipe deve confirmar qual descrição corresponde à necessidade, sem concluir equivalência entre os códigos.'),
      section('Faça uma última conferência','Antes de avançar, verifique se modelo, ano, versão, posição e quantidade estão claros na resposta da loja. Caso alguma informação conflite com a indicação do profissional, interrompa a escolha e esclareça a diferença.','Está procurando kits para a picape Hilux? Consulte os itens abaixo e envie os dados completos à RochaPro para conferir aplicação e disponibilidade.')
    ],['KIT10124','KIT10061']),
  entry('hilux','hilux-como-pedir-peca-por-codigo','Cotação da Hilux: uma mensagem completa evita várias idas e voltas',
    'Veja quais informações reunir para consultar kits da Hilux: dados do veículo, posição da peça, medidas indicadas e código do catálogo.', 'Entenda o catálogo',
    'Uma cotação fica mais rápida quando a primeira mensagem já identifica a necessidade. Não se trata de fazer o trabalho da oficina, mas de levar ao atendimento os dados que ela apurou. Isso ajuda a comparar o que foi pedido com o que foi oferecido.',[
      section('Reúna quatro grupos de informação','Primeiro, os dados do veículo: modelo completo, ano e versão. Depois, o conjunto e a posição da peça. Em seguida, a indicação técnica recebida, incluindo medidas quando necessárias. Por último, o código encontrado no catálogo, se você já tiver uma referência.','Se algum dado estiver faltando, diga isso. Uma dúvida explícita pode ser resolvida; uma informação presumida pode passar despercebida até a separação do produto.'),
      section('Não elimine a medida da descrição','No cadastro da Hilux, KIT10115, KIT10141 e KIT10119 trazem referências de 35 mm, 38 mm e 40 mm em aplicações de amortecedor dianteiro. Os intervalos e as descrições devem ser lidos por inteiro. '+ref('catalog')+'.','Esses números ilustram por que “bucha dianteira” é uma mensagem incompleta. Não são um convite para medir a peça de forma improvisada nem uma regra para escolher apenas pelo ano do veículo.'),
      section('Peça uma resposta que possa ser conferida','Solicite código, descrição, quantidade e confirmação da aplicação. Se a oficina indicou um componente e a resposta mencionar outro, esclareça antes de comparar valores. Um orçamento organizado deve permitir que cliente, loja e profissional estejam falando do mesmo item.','Quando houver foto, use-a como apoio de identificação. Perspectiva, desgaste e ausência de escala podem impedir conclusões sobre dimensão a partir da imagem.'),
      section('Use um modelo simples de mensagem','Você pode escrever: “Tenho uma Hilux, ano e versão abaixo. A oficina indicou esta peça, nesta posição e com estas informações. Encontrei o código no catálogo; podem conferir a aplicação e a disponibilidade?”. Anexe somente os dados necessários à consulta.','Abra os kits abaixo e fale com a RochaPro. A cotação começa pela identificação correta, e a equipe pode orientar quais informações ainda faltam.')
    ],['KIT10115','KIT10141','KIT10119']),
  entry('hilux','hilux-estrada-rural-caderno-uso','Hilux na estrada rural: o caderno de uso que ajuda na revisão',
    'Registre trajetos, carga e mudanças percebidas na Hilux para conversar melhor com a oficina e selecionar peças a partir do diagnóstico.', 'Organização da manutenção',
    '“Roda na roça” pode descrever realidades muito diferentes. Há trajetos curtos, longas viagens, períodos de chuva e dias de uso quase todo urbano. Um registro simples ajuda a explicar essa rotina sem transformar cada caminho em uma história difícil de reconstruir.',[
      section('Descreva a rotina em vez de dar uma nota','Anote frequência dos trajetos, duração aproximada e tipos de piso encontrados. Registre quando o uso muda, como em uma temporada com mais viagens ou transporte diferente do habitual. Essas informações ajudam a contextualizar a avaliação do veículo.','Não invente um intervalo de manutenção com base apenas nessas anotações. A documentação da versão e a orientação do profissional continuam sendo as referências para planejar os serviços.'),
      section('Observe sem diagnosticar','Se perceber algo diferente, registre em que situação ocorreu e se voltou a acontecer. Evite concluir que determinado ruído corresponde a uma bucha específica. A anotação deve preservar o que foi observado, para que a oficina investigue o conjunto.','Caso a mudança comprometa a condução ou gere dúvida sobre a segurança do uso, procure avaliação antes de continuar o trajeto. Não é necessário repetir uma condição problemática para produzir um relato mais detalhado.'),
      section('Conecte a avaliação ao catálogo','Quando houver indicação de peça, confira a descrição e a posição. O KIT10061 aparece ligado ao feixe de molas e antirruído da Hilux; o KIT10062 tem sua própria descrição para o feixe traseiro. A presença na mesma família não torna os códigos equivalentes. '+ref('catalog')+'.','Mantenha no registro o código efetivamente utilizado e a ordem de serviço. Na próxima revisão, essa informação será mais clara do que lembrar apenas que “mexeram na traseira”.'),
      section('Transforme a rotina em planejamento','Antes de uma mudança de uso, compartilhe o caderno com a oficina e discuta o que precisa ser avaliado. Depois, atualize as anotações com as conclusões. O valor do histórico está nessa continuidade, não no tamanho do documento.','Sua Hilux teve uma necessidade identificada? Consulte os kits abaixo e envie ano, versão e posição da peça à RochaPro para conferir a aplicação.')
    ],['KIT10061','KIT10062']),
  entry('l200','l200-triton-comunidade-historias','L200 e Triton: quando a picape ajuda a reunir pessoas',
    'A identidade dos proprietários da L200 aparece em clubes e relatos de viagens. Conheça esse contexto sem confundir afinidade com aplicação de peças.', 'Comunidades',
    'Há quem conheça a L200 pelo trabalho e quem associe a picape à primeira viagem em grupo. As duas histórias podem se encontrar na mesma comunidade. O ponto em comum nem sempre é uma preparação especial: muitas vezes é a vontade de conversar sobre um veículo presente na rotina.',[
      section('Um nome que vira identidade de grupo','O Triton 4x4 Club conta sua origem a partir de proprietários da L200 Triton e registra encontros e viagens em sua história. É um testemunho de identidade compartilhada, mas a página histórica não mede atividade ou número de membros hoje. '+ref('tritonClub')+'.','Esse contexto sugere boas perguntas para uma conversa entre donos: como o carro entrou na família, qual foi o primeiro passeio e que cuidado passou a fazer parte da rotina depois dele.'),
      section('Diferentes usos cabem na mesma conversa','Quem usa a picape no trabalho pode contribuir com organização de manutenção. Quem viaja pode compartilhar como prepara documentos e bagagem. Nenhum desses relatos, sozinho, define a condição de outra L200 ou a peça necessária para ela.','Ao contar uma experiência, inclua versão e contexto. O nome L200 reúne aplicações diferentes no catálogo, e a palavra Triton também precisa ser acompanhada de dados do veículo.'),
      section('A identificação protege a boa indicação','KIT10234 está cadastrado para o feixe de molas da L200 Triton. KIT10002 apresenta outras versões na descrição, como L, GL, GLS, HPE, Savana, Sport e Outdoor. Leia os cadastros completos antes de usar a recomendação de outro proprietário. '+ref('catalog')+'.','Essa separação permite aproveitar a conversa da comunidade sem transformar afinidade pelo modelo em uma conclusão sobre compatibilidade.'),
      section('Conte a sua história e organize o próximo cuidado','Guarde fotos autorizadas, registros dos passeios e documentos dos serviços. A memória afetiva e a memória da manutenção podem andar juntas, desde que cada uma preserve seu papel.','Qual é a história da sua L200? Conte à RochaPro e, se houver um reparo indicado, consulte os kits abaixo com ano, versão e posição da peça em mãos.')
    ],['KIT10234','KIT10002'],['tritonClub','catalog']),
  entry('l200','l200-gl-gls-outdoor-triton-aplicacao','L200, Outdoor ou Triton: por que a versão precisa entrar no pedido',
    'O catálogo da L200 tem recortes de versão e período. Veja como localizar a aplicação sem escolher um kit apenas pelo nome da picape.', 'Aplicação de peças',
    'A família L200 aparece no catálogo com várias identificações. Quando a cotação omite a versão, a busca perde uma informação importante. Acrescentar GL, GLS, Sport, Outdoor ou Triton, conforme o veículo, ajuda a iniciar a consulta no lugar certo.',[
      section('Copie os dados, não confie só na lembrança','Confira a identificação do veículo e os documentos de manutenção disponíveis. Anote ano de fabricação, ano-modelo e versão. Se houver divergência entre um anúncio antigo e a documentação, peça esclarecimento antes de escolher uma peça.','Não deduza a aplicação apenas pelo motor ou pela aparência da carroceria. O conjunto que será reparado e a descrição do produto também precisam entrar na conferência.'),
      section('Veja as diferenças nos próprios códigos','O KIT10543 menciona L200 GL/GLS quadrada na aplicação da estabilizadora. O KIT10376 traz L200 GL de 2005/2006. Já o KIT10234 se refere ao feixe de molas da Triton. São descrições que direcionam consultas diferentes. '+ref('catalog')+'.','O exemplo não pretende mapear todas as gerações da L200. Ele mostra que uma busca ampla pelo modelo deve ser seguida de uma leitura cuidadosa de cada aplicação.'),
      section('Um nome conhecido pode esconder uma informação faltante','Mesmo quando o proprietário reconhece a versão, pode faltar a posição ou uma medida indicada pela oficina. Mantenha essas dúvidas abertas até serem conferidas. Um campo sem informação não deve ser interpretado como compatibilidade universal.','Se o conjunto passou por alteração, informe isso ao profissional e à loja. A aplicação original do veículo pode não descrever o que está instalado atualmente.'),
      section('Confira a resposta antes de comparar preços','Verifique se o orçamento repete corretamente a versão, o conjunto e o código solicitado. Só depois compare condições comerciais entre produtos correspondentes à mesma necessidade. Isso evita colocar lado a lado kits com funções diferentes.','Envie os dados da sua L200 à RochaPro e consulte os itens abaixo. A equipe pode ajudar a localizar o cadastro para confirmar a aplicação indicada na revisão.')
    ],['KIT10543','KIT10376','KIT10234']),
  entry('l200','l200-feixe-molas-amortecedor-kits','L200: feixe de molas e amortecedor pedem consultas diferentes',
    'Aprenda a separar conjunto, posição e medida ao consultar kits da L200, com exemplos do catálogo para Sport, HPE e Triton.', 'Entenda o catálogo',
    'Uma conversa sobre a suspensão pode misturar componentes de conjuntos diferentes. Para comprar a peça indicada, é melhor sair da expressão genérica “kit da L200” e registrar exatamente onde o reparo será realizado.',[
      section('Comece pelo conjunto avaliado','Pergunte à oficina se a indicação envolve feixe de molas, amortecedor, estabilizadora ou outro conjunto. Em seguida, peça a posição e a descrição do componente. A sequência ajuda a evitar que um resultado de busca parecido desvie a consulta.','Não use a existência de um kit como motivo para substituir peças. O catálogo organiza produtos; quem avalia o veículo identifica a necessidade e define o serviço adequado.'),
      section('Confira os recortes do catálogo','O KIT10288 aparece para feixe de molas traseiro da L200 Sport/HPE. O KIT10204 é descrito para amortecedor dianteiro inferior da Triton com referência de 37 mm. O KIT10615 apresenta referência de 35 mm e período de 2012 a 2020. '+ref('catalog')+'.','Essas descrições não são equivalentes. Medida, posição e período precisam ser confirmados para a peça indicada, sem extrapolar de uma versão para outra.'),
      section('Use o orçamento como documento de conferência','Peça que o código venha acompanhado da descrição completa. Se a peça precisar ser identificada por medida, a informação deve ser obtida de forma apropriada pelo profissional. Uma foto sem escala não resolve todas as dúvidas.','Mantenha também a quantidade solicitada e o que está incluído no conjunto. A palavra “kit” pode reunir composições diferentes, por isso o número de itens não deve ser presumido.'),
      section('Registre o que foi instalado','Depois do serviço, guarde a referência efetivamente utilizada e a posição atendida. Esse registro ajuda na próxima avaliação e evita reconstruir todo o histórico a partir da lembrança de uma compra.','A oficina já identificou a necessidade da sua L200? Consulte os kits abaixo e fale com a RochaPro com ano, versão, posição e medidas indicadas para conferir a aplicação.')
    ],['KIT10288','KIT10204','KIT10615']),
  entry('ranger','ranger-clube-historias-familia','Ranger: a picape que também guarda histórias de família',
    'Um relato recente do Ranger Clube Brasil mostra o lado afetivo da picape. Veja como ligar memória, encontros e organização da manutenção.', 'Comunidades',
    'Algumas picapes deixam de ser lembradas apenas pelo ano ou pela versão. Elas passam a representar uma viagem, uma fase da família ou um projeto de conservação. A Ranger aparece nesse tipo de história, e a comunidade oferece espaço para compartilhá-la.',[
      section('Um relato recente de pertencimento','Em texto publicado no portal Ford em 16 de novembro de 2026, o presidente do Ranger Clube Brasil descreve encontros familiares e a restauração de uma Ranger 1996. É um relato do próprio participante, não uma pesquisa independente sobre todos os donos do modelo. '+ref('rangerClub')+'.','A força da pauta está na experiência: conservar o carro, conhecer outras pessoas e encontrar um motivo para reunir gerações. Não é preciso transformar cada história em comparação de desempenho.'),
      section('Conte o que torna a sua Ranger particular','Registre como ela chegou à família, quais viagens marcaram sua trajetória e o que você pretende preservar. Se houver um projeto de recuperação, separe a parte afetiva das decisões técnicas que exigem avaliação do veículo.','Fotos antigas e relatos ajudam a reconstruir a memória. Notas, ordens de serviço e códigos ajudam a reconstruir a manutenção. Os dois arquivos se complementam, mas um não substitui o outro.'),
      section('A geração precisa acompanhar a indicação','No catálogo RochaPro, o KIT10239 traz aplicação de amortecedor dianteiro da Ranger de 1994 a 1997. O KIT10088 se refere ao feixe de molas e jumelo traseiro até 2011. São recortes específicos, que não podem ser estendidos às Rangers atuais por afinidade com o nome. '+ref('catalog')+'.','Ao trocar uma recomendação com outro dono, pergunte qual era o carro e qual conjunto foi atendido. Essa informação torna a conversa mais útil e evita generalizações.'),
      section('Preserve a história e documente o cuidado','Depois de cada serviço, atualize o histórico e mantenha a referência da peça. Se participar de um encontro, peça autorização antes de divulgar imagens ou histórias de outras famílias.','Que capítulo da sua Ranger merece ser contado? Compartilhe com a RochaPro e, para uma revisão indicada, confira os kits abaixo com os dados completos do veículo.')
    ],['KIT10239','KIT10088'],['rangerClub','catalog']),
  entry('ranger','ranger-1994-2011-bieletas-aplicacao','Ranger antiga: atenção aos anos na consulta de bieletas e buchas',
    'As aplicações da Ranger mudam conforme o código. Compare os recortes de 1994–1997 e 1999–2011 sem presumir intercâmbio entre peças.', 'Aplicação de peças',
    'Na procura por peças para uma Ranger antiga, “primeira geração” ou “modelo antigo” podem ser expressões amplas demais. O catálogo trabalha com descrições e períodos específicos. Ler esses limites é mais útil do que tentar escolher pela semelhança da fotografia.',[
      section('Identifique o veículo e o conjunto','Registre ano de fabricação, ano-modelo e versão. Peça à oficina a indicação da posição e da peça necessária. Se o veículo tem histórico de alterações, inclua essa informação, pois a identificação original não garante que todos os conjuntos permaneçam iguais.','Também diferencie uma informação comprovada de uma lembrança do antigo proprietário. Essa separação ajuda o profissional a saber o que ainda precisa verificar.'),
      section('Compare os códigos com calma','O KIT10371 é apresentado para bieleta da Ranger americana de 1994 a 1997. O KIT10315 traz aplicação de bieleta dianteira de 1999 a 2011. O KIT10312 se refere à posição superior do amortecedor dianteiro de 1998 a 2011. '+ref('catalog')+'.','Os exemplos mostram dois cuidados: períodos diferentes e componentes diferentes. Nenhum deles autoriza concluir que um ano não mencionado está coberto ou que um código substitui outro.'),
      section('Um intervalo incompleto é uma pergunta','Se seu veículo estiver em um ano de transição ou fora do período descrito, peça conferência. Não amplie a faixa por conta própria. Da mesma forma, quando a descrição trouxer uma origem ou configuração específica, preserve essa informação na mensagem.','Na comparação de valores, confirme que os orçamentos tratam do mesmo conjunto, quantidade e aplicação. Caso contrário, o preço menor pode estar ligado a uma necessidade diferente.'),
      section('Guarde a referência confirmada','Depois de identificado o produto, mantenha o código junto da ordem de serviço. Essa anotação facilita futuras consultas sem transformar a compra anterior em uma recomendação automática para qualquer outro reparo.','Está revisando uma Ranger desse período? Envie à RochaPro os dados do veículo e a indicação da oficina. Os kits abaixo ajudam a iniciar a consulta com descrições claras.')
    ],['KIT10371','KIT10315','KIT10312']),
  entry('ranger','ranger-cabine-feixe-jumelo','Ranger: cabine, feixe de molas e jumelo não são a mesma cotação',
    'Entenda como separar os conjuntos citados no orçamento da Ranger e localizar os códigos de kits antes de consultar disponibilidade.', 'Entenda o catálogo',
    'Quando a conversa começa com “tem um incômodo vindo de trás”, ainda faltam muitas informações para comprar uma peça. A localização percebida pelo motorista não identifica, sozinha, o componente. O caminho passa pela avaliação e pela descrição do conjunto.',[
      section('Descreva o que acontece','Anote a condição em que a mudança foi percebida e compartilhe o histórico recente com a oficina. Evite escolher uma peça para que o profissional apenas confirme sua hipótese. Uma investigação aberta pode apontar um conjunto diferente do imaginado.','Não reproduza uma situação que pareça insegura para tentar localizar um ruído. A avaliação deve ser feita de forma adequada, com as informações que você já conseguiu observar.'),
      section('Leia as famílias de aplicação','O KIT10021 aparece no catálogo como coxins de cabine da Ranger a partir de 1998. O KIT10088 corresponde ao feixe de molas e jumelo traseiro até 2011, e o KIT10287 ao jumelo traseiro até 2011. '+ref('catalog')+'.','A diferença entre cabine e conjunto traseiro deve permanecer clara no pedido. Mesmo entre dois códigos relacionados ao feixe ou ao jumelo, composição e aplicação precisam ser conferidas; não há equivalência presumida.'),
      section('Peça o detalhamento da necessidade','Solicite posição, quantidade e descrição. Se a indicação da oficina for apenas verbal, registre uma mensagem e confirme se você entendeu corretamente. Esse cuidado evita que o pedido mude de sentido ao passar por mais de uma pessoa.','Também informe alterações conhecidas e serviços anteriores. O código que serviu em outra Ranger, ou mesmo em outro conjunto da sua, não resolve sozinho a consulta atual.'),
      section('Feche o registro depois do serviço','Guarde o orçamento aprovado, os códigos utilizados e a conclusão da avaliação. Se a situação persistir, retorne ao profissional com esse histórico, sem iniciar uma sequência de trocas por tentativa.','Consulte os kits abaixo e fale com a RochaPro com ano, versão e a indicação do conjunto. A equipe poderá verificar as aplicações cadastradas e a disponibilidade.')
    ],['KIT10021','KIT10088','KIT10287']),
  entry('frontier','frontier-comunidade-perguntas-por-geracao','Frontier: uma comunidade fica mais útil quando identifica a geração',
    'O Clube da Nissan Frontier organiza conteúdos por geração. Esse cuidado também melhora as perguntas sobre manutenção e aplicação de kits.', 'Comunidades',
    'Um fórum pode reunir uma enorme variedade de experiências com a Frontier. Para aproveitar a conversa, o detalhe mais importante costuma aparecer antes da resposta: de qual veículo estamos falando? Ano, versão e histórico dão contexto ao que outro proprietário relata.',[
      section('A organização do conteúdo já ensina algo','O site do Clube da Nissan Frontier mantém publicações de 2025 e categorias por geração. Essa estrutura é um sinal de produção própria de conhecimento, embora não revele quantos membros estão ativos ou qual é o alcance atual. '+ref('frontierClub')+'.','Separar os assuntos ajuda o leitor a não misturar experiências de carros diferentes. O mesmo princípio vale para uma conversa em aplicativo: uma pergunta bem identificada tende a receber respostas mais úteis.'),
      section('Escreva a pergunta antes de procurar a solução','Informe os dados do carro, o que mudou e quando você percebeu a mudança. Acrescente serviços recentes relevantes e diga se já houve avaliação profissional. Evite começar por uma conclusão sobre qual peça está defeituosa.','Ao ler uma resposta, procure o mesmo contexto. Uma solução que funcionou em outro ano ou conjunto pode não corresponder à necessidade do seu veículo.'),
      section('Leve a referência para a oficina','Guarde o link ou o código mencionado e pergunte se ele se aplica ao diagnóstico. No catálogo, KIT10238 traz estabilizadora dianteira da Frontier até 2007; KIT10242 se refere ao feixe de molas e jumelo traseiro até 2012. '+ref('catalog')+'.','São exemplos de recortes que precisam acompanhar a recomendação. O nome Frontier, sozinho, não torna as peças adequadas a qualquer geração.'),
      section('Devolva uma resposta útil à comunidade','Depois da avaliação, compartilhe o que foi confirmado, preservando dados pessoais e informações de terceiros. Diferencie a hipótese inicial do diagnóstico final. Assim, quem encontrar a conversa depois terá um registro mais completo.','Sua Frontier precisa de uma peça identificada? Confira os kits abaixo e envie à RochaPro ano, versão e posição do componente para consultar a aplicação.')
    ],['KIT10238','KIT10242'],['frontierClub','catalog']),
  entry('frontier','frontier-ruido-como-relatar-oficina','Ruído na Frontier: como descrever o problema sem adivinhar a peça',
    'Um relato objetivo ajuda a oficina a investigar a Frontier. Veja o que anotar, como organizar o histórico e quando consultar códigos de kits.', 'Organização da manutenção',
    'É comum perceber um barulho e procurar na internet uma peça que pareça explicar o problema. Uma abordagem mais útil começa pelo relato: o que você ouviu, em qual condição e o que mudou recentemente. A causa deve ser apurada na avaliação do veículo.',[
      section('Registre a circunstância','Anote se a percepção ocorreu ao iniciar um deslocamento, passar por uma irregularidade ou em outra situação observada. Diga se aconteceu uma vez ou se voltou a aparecer. Não é preciso usar um vocabulário técnico para descrever a experiência.','Evite afirmar “é a bucha” quando isso ainda é uma hipótese. Também não tente repetir uma condição perigosa para gravar áudio ou vídeo; leve à oficina o que já conseguiu observar com segurança.'),
      section('Recupere o histórico recente','Informe serviços executados, peças substituídas e alterações conhecidas. Se o carro acabou de passar por uma intervenção, guarde a ordem de serviço e relate a sequência dos acontecimentos. O objetivo é fornecer contexto, não atribuir responsabilidade sem avaliação.','Uma nota curta com datas e quilometragem registrada costuma ser mais clara do que várias mensagens desconectadas. Mantenha o relato inicial para compará-lo com a conclusão do profissional.'),
      section('Só então consulte a aplicação','Se o diagnóstico indicar a posição inferior do amortecedor dianteiro, por exemplo, o catálogo da Frontier apresenta KIT10116 com referência de 37 mm e KIT10117 com 41,5 mm, nas aplicações descritas. A diferença não deve ser resolvida por suposição. '+ref('catalog')+'.','Medidas, ano, versão e posição precisam ser conferidos. A lista não recomenda a troca desses componentes para qualquer ruído; ela mostra por que a consulta vem depois da identificação da necessidade.'),
      section('Feche o ciclo do atendimento','Depois do serviço, registre o diagnóstico e os códigos utilizados. Caso o comportamento continue, retorne com esse histórico ao profissional, em vez de começar uma nova tentativa de troca baseada em outro relato.','Recebeu indicação de peças para sua Frontier? Envie os dados completos à RochaPro e consulte os kits abaixo para verificar aplicação e disponibilidade.')
    ],['KIT10116','KIT10117']),
  entry('frontier','frontier-feixe-jumelo-ler-catalogo','Frontier: como ler uma aplicação de feixe de molas e jumelo',
    'O catálogo separa conjuntos e períodos da Frontier. Veja o que conferir antes de usar uma indicação de kit traseiro em outra versão.', 'Entenda o catálogo',
    'O catálogo pode ajudar a organizar uma dúvida, desde que o leitor respeite o recorte escrito em cada produto. Na Frontier, um código que menciona feixe de molas ou jumelo não deve ser tratado como solução genérica para toda a linha.',[
      section('Localize o conjunto do seu veículo','Peça à oficina que identifique o conjunto instalado e a posição do componente indicado. Não comece assumindo que a estrutura de uma Frontier de outro ano seja igual à sua. A documentação da versão e a avaliação presencial orientam essa identificação.','Se houve modificação anterior, inclua essa informação. O histórico pode ser necessário para entender por que uma descrição de aplicação original não corresponde ao que está no carro.'),
      section('Leia os dois códigos sem abreviar','KIT10242 aparece como aplicação de feixe de molas e jumelo traseiro da Frontier até 2012. KIT10207 é descrito para jumelo da mola traseira até 2012. A aproximação dos nomes não comprova que composição ou quantidade sejam iguais. '+ref('catalog')+'.','O limite de ano também deve permanecer na conversa. Não estenda a indicação a uma Frontier posterior porque um anúncio usa apenas o nome do modelo em destaque.'),
      section('Compare o orçamento com a indicação','Confirme se o código atende ao conjunto e à quantidade apontados pela oficina. Pergunte o que está incluído no kit e quais dados faltam para confirmar a aplicação. Uma foto ajuda a reconhecer o produto, mas não substitui essa checagem.','Se a descrição não corresponde ao seu veículo, peça orientação em vez de buscar um item “parecido”. O atendimento pode continuar mesmo quando a primeira referência não é a correta.'),
      section('Mantenha o pedido rastreável','Guarde código, descrição e resposta de aplicação junto do orçamento. Depois do serviço, registre o que foi efetivamente utilizado. Isso facilita uma futura conversa e reduz a dependência de nomes informais.','Consulte os kits abaixo e envie à RochaPro ano, versão e a posição indicada para sua Frontier. A equipe poderá conferir os itens cadastrados antes de avançar com a cotação.')
    ],['KIT10242','KIT10207']),
  entry('s10','s10-blazer-memoria-comunidade','S10 e Blazer: a memória dos encontros também faz parte da garagem',
    'Clubes históricos de S10 e Blazer revelam histórias de convivência. Veja como valorizar essa memória e manter o cuidado com a aplicação das peças.', 'Comunidades',
    'Uma fotografia de encontro antigo pode contar mais do que a ficha técnica: mostra quem estava ali, como os carros eram usados e quais amizades continuaram. Para donos de S10 e Blazer, esse acervo é uma porta de entrada para histórias de conservação e convivência.',[
      section('Uma referência histórica, com data no contexto','O Clube do Vortec apresenta memória de encontros de S10, Blazer e outros modelos com motor Vortec 4.3 V6. Os registros históricos consultados não comprovam agenda ativa em 2026, nem representam todas as motorizações dessas linhas. '+ref('vortecClub')+'.','O interesse está em reconhecer que existe uma cultura construída em torno dos carros. Antes de divulgar um encontro atual ou buscar contato, é necessário confirmar os canais e a atividade recente do grupo.'),
      section('Conte histórias com identificação','Ao publicar uma foto antiga, registre local e data quando conhecidos, além da versão do veículo. Peça autorização às pessoas identificáveis e evite preencher lacunas com suposições. Uma memória incompleta pode continuar interessante sem ganhar detalhes inventados.','Se a conversa envolver manutenção, separe o que foi feito naquele carro do que pode ser indicado para outro. O vínculo com o modelo não confirma compatibilidade de componentes.'),
      section('O catálogo também pede esse cuidado','O KIT10006 tem descrição para bieletas dianteiras de S10/Blazer de 1995 a 2011. O KIT10461 traz referência de estabilizadora dianteira de 26 mm e período definido. A versão e as medidas precisam ser conferidas, inclusive quando o nome do veículo aparece no produto. '+ref('catalog')+'.','Uma indicação de grupo pode ser o início da pesquisa, mas o pedido precisa corresponder ao diagnóstico e à configuração do seu carro.'),
      section('Preserve o que vale compartilhar','Guarde imagens, documentos de serviços e relatos com suas origens. Assim, a história do veículo não depende apenas de lembranças e pode acompanhar uma futura mudança de proprietário.','Qual encontro ou viagem marcou sua S10 ou Blazer? Conte à RochaPro e, se houver reparo identificado, consulte os kits abaixo com ano, versão e posição da peça.')
    ],['KIT10006','KIT10461'],['vortecClub','catalog']),
  entry('s10','s10-1995-2011-bieleta-estabilizadora','S10 de 1995 a 2011: bieleta e estabilizadora na leitura do orçamento',
    'Veja como diferenciar as descrições de kits da S10 antiga e conferir ano, posição e medida antes de pedir peças para a revisão.', 'Entenda o catálogo',
    'Na revisão da S10, o nome popular de uma peça pode circular de formas diferentes. Para evitar ambiguidades, a cotação deve manter a descrição do conjunto e do componente. É um cuidado simples que ajuda cliente, oficina e loja a falar da mesma necessidade.',[
      section('Peça uma indicação completa','Solicite à oficina o nome da peça, a posição e a quantidade necessária. Se houver uma medida relevante, ela deve acompanhar o pedido. Não transforme “conferir a dianteira” em uma lista de compras antes que a avaliação esteja concluída.','Quando receber um código de referência, guarde a descrição associada. Um número sem contexto pode ser copiado corretamente e ainda assim se referir a outro serviço.'),
      section('Compare exemplos reais do catálogo','O KIT10006 é descrito como conjunto de duas bieletas dianteiras para S10/Blazer de 1995 a 2011, em borracha de pneu lonada. O KIT10461 menciona estabilizadora dianteira de 26 mm no período cadastrado. '+ref('catalog')+'.','A presença de ambos na família S10 não torna os itens equivalentes. Medida, composição e aplicação devem ser conferidas com a necessidade indicada, sem presumir que toda configuração do período use o mesmo produto.'),
      section('Cuidado com a foto fora de contexto','Uma imagem pode ajudar a reconhecer formato e composição, mas não comprova a medida ou a aplicação. Compare o código da fotografia com o código do orçamento e peça esclarecimento se a descrição não estiver completa.','Se o veículo recebeu alterações ao longo dos anos, informe isso. A referência original da S10 pode não descrever integralmente o conjunto instalado hoje.'),
      section('Finalize com uma conferência conjunta','Antes de concluir o pedido, confirme que ano, versão, posição e quantidade estão registrados. Depois do serviço, guarde a referência efetivamente utilizada junto da ordem de serviço para facilitar futuras avaliações.','A oficina indicou peças para sua S10? Abra os kits abaixo e fale com a RochaPro com os dados do veículo. A equipe pode conferir as aplicações e a disponibilidade para a cotação.')
    ],['KIT10006','KIT10461']),
  entry('s10','s10-mudanca-ano-feixe-molas','S10: por que um kit traseiro de outra época pode não ser o seu',
    'Compare recortes do catálogo da S10 para 2001–2011 e 2013 em diante e entenda por que posição e função precisam acompanhar o ano.', 'Aplicação de peças',
    'Quando uma picape passa muitos anos no mercado, a busca pelo nome reúne veículos e peças de épocas diferentes. Na S10, olhar apenas a palavra “traseiro” deixa informações essenciais de fora. Ano, função e posição precisam aparecer juntos.',[
      section('O ano organiza a busca, mas não a encerra','Registre fabricação, ano-modelo e versão. Depois, identifique com a oficina qual componente foi indicado. Esses dados trabalham em conjunto: encontrar o período certo não significa que qualquer kit listado nele atende ao reparo.','Se a aplicação estiver no limite de um intervalo ou não for clara, peça confirmação. Não use uma semelhança visual para preencher um ano ausente na descrição.'),
      section('Leia a função além do período','KIT10005 aparece para antirruído do feixe de molas traseiro da S10 de 2001 a 2011. KIT10004 tem descrição para feixe de molas traseiro a partir de 2013. Além dos anos, as próprias descrições indicam consultas distintas. '+ref('catalog')+'.','O KIT10472, por sua vez, menciona a parte dianteira da mola traseira de 2012 a 2020. “Dianteira” aqui faz parte de uma posição dentro do conjunto traseiro; por isso a leitura não deve parar na primeira palavra.'),
      section('Não faça uma lista de trocas por aproximação','Se a oficina indicou um componente, procure a referência correspondente. Um kit de composição diferente pode não responder à mesma necessidade, mesmo quando seu título parece mais abrangente. Pergunte o que está incluído e preserve a orientação do diagnóstico.','O catálogo não determina intervalos de substituição nem comprova que um incômodo será resolvido com determinado código. Ele permite localizar produtos para uma necessidade já identificada.'),
      section('Registre a escolha confirmada','Mantenha código, descrição e dados do veículo na mesma cotação. Ao final do serviço, guarde o registro de aplicação. A próxima busca ficará mais objetiva, sem depender de reconstruir a informação a partir de uma embalagem antiga.','Consulte abaixo os kits citados e envie à RochaPro os dados da sua S10 para conferir aplicação, composição e disponibilidade.')
    ],['KIT10005','KIT10004','KIT10472']),
  entry('jimny','jimny-comunidade-passeios-familia','Jimny: o passeio em grupo começa pela escolha da experiência',
    'A cultura de passeios do Jimny reúne perfis diferentes. Veja o que perguntar à organização e como respeitar o recorte dos kits disponíveis.', 'Comunidades',
    'O tamanho do carro não define o tamanho das histórias que ele reúne. No Jimny, um passeio pode ser o motivo para conhecer pessoas, descobrir um destino e começar um álbum de viagens. A escolha do programa, porém, deve acompanhar o perfil dos ocupantes e do veículo.',[
      section('Há formatos diferentes de participação','A página oficial do Suzuki Day apresenta propostas distintas de passeio e calendário de 2026. Ela identifica Jimny e Jimny Sierra separadamente entre os modelos. Isso documenta uma iniciativa da marca, sem revelar o tamanho de uma comunidade independente. '+ref('suzukiDay')+'.','Antes de se interessar por uma edição futura, confira as informações atualizadas diretamente com a organização. Calendário passado e imagens de uma etapa não descrevem as condições de outra.'),
      section('Pergunte antes de decidir','Entenda duração, roteiro, apoio, regras e alternativas de retorno. Conte à organização se é sua primeira participação e quais são as necessidades dos acompanhantes. Uma proposta adequada é aquela que faz sentido para o seu momento, não a que parece mais impressionante na foto.','Converse também com a oficina sobre o estado do carro e o uso previsto. Participar de um evento não transforma uma lista genérica de acessórios ou peças em preparação obrigatória.'),
      section('Separe comunidade de aplicação comercial','Na consulta de novembro de 2026, o catálogo RochaPro possui o KIT10452 para braço tensor traseiro do Jimny de 2010 a 2021, sem foto publicada. Esse cadastro não confirma aplicação no Sierra. '+ref('catalog')+'.','A existência de conteúdo para a comunidade não significa que a loja ofereça todos os componentes ou todas as gerações. O código deve ser conferido para a necessidade real do veículo.'),
      section('Guarde a experiência que você quer repetir','Depois do passeio, registre o que funcionou para o grupo, o que mudaria no planejamento e quais dúvidas surgiram sobre o carro. Esse diário ajuda a escolher a próxima experiência com mais clareza.','Tem um Jimny e recebeu indicação para o conjunto citado? Consulte o kit abaixo e envie ano, versão e posição da peça à RochaPro para confirmar a aplicação e solicitar informações.')
    ],['KIT10452'],['suzukiDay','catalog']),
  entry('jimny','jimny-sierra-conferir-aplicacao-kit','Jimny e Jimny Sierra: confirme a aplicação antes de seguir uma indicação',
    'O KIT10452 cita Jimny de 2010 a 2021. Entenda o que esse cadastro informa e por que ele não autoriza estender a aplicação ao Sierra.', 'Aplicação de peças',
    'Em grupos e resultados de busca, Jimny e Jimny Sierra podem aparecer na mesma conversa. Para escolher peças, a identificação precisa ser mais específica. O compartilhamento de uma comunidade não prova que os componentes sejam intercambiáveis.',[
      section('Comece pelo nome completo do veículo','Informe ano de fabricação, ano-modelo e versão conforme a documentação. Se a pergunta veio de um anúncio ou de outro proprietário, preserve o código e a descrição original para que a equipe possa conferir a referência.','Evite concluir a configuração apenas pela fotografia. O atendimento deve trabalhar com dados do veículo e com a identificação do conjunto que foi avaliado.'),
      section('Leia exatamente o que está cadastrado','O KIT10452 está descrito para braço tensor traseiro do Jimny de 2010 a 2021. Na consulta de novembro de 2026, é o único kit com Jimny no nome do catálogo público RochaPro e ainda não possui foto publicada. '+ref('catalog')+'.','Esse texto não comprova aplicação no Jimny Sierra nem cobertura de todos os componentes do Jimny. Se o seu caso não estiver claro na descrição, a dúvida precisa ser resolvida antes de considerar a compra.'),
      section('Uma imagem ausente pede informação','Solicite detalhes do item à equipe, mantendo o código na conversa. Não substitua a referência por outro produto visualmente parecido encontrado na internet. Mesmo com fotografia disponível, posição, medidas e aplicação continuariam exigindo conferência.','A oficina deve identificar a necessidade e o conjunto. A loja pode verificar o cadastro e a disponibilidade, sem transformar uma consulta remota em diagnóstico do veículo.'),
      section('Faça uma pergunta que possa ser respondida','Envie os dados completos, a posição indicada e as informações que o profissional conseguiu apurar. Peça confirmação expressa da aplicação do código para esse caso. Se faltarem dados, complete a consulta em vez de assumir compatibilidade.','Precisa verificar o KIT10452? Abra o item abaixo e fale com a RochaPro. O objetivo é confirmar a aplicação correta antes de avançar com a cotação.')
    ],['KIT10452']),
  entry('d20','d20-memoria-conservacao-historico','D20: conservar a história também é documentar os cuidados',
    'A D20 aparece em encontros de antigos e histórias familiares. Veja como organizar a memória do veículo e os registros de manutenção.', 'Histórias de garagem',
    'Uma D20 pode carregar lembranças de trabalho, viagens e pessoas que passaram pela mesma cabine. Conservar essa história envolve mais do que guardar fotografias. Também vale registrar intervenções e referências que ajudem a entender o carro que chegou até hoje.',[
      section('A memória aparece nos encontros','Em setembro de 2025, a Prefeitura de Caxias relatou um passeio de veículos antigos que incluiu a D20. É um registro de participação em atividade cultural multimarcas, não uma medida do tamanho de um clube exclusivo do modelo. '+ref('d20Culture')+'.','A pauta abre espaço para relatos de proprietários: de onde veio a picape, que função cumpriu e o que cada família decidiu preservar. Nem toda história precisa começar por uma restauração completa.'),
      section('Crie dois arquivos que se complementam','No primeiro, reúna fotos, relatos e datas conhecidas. No segundo, mantenha notas, ordens de serviço, códigos e observações da oficina. Quando uma informação for apenas lembrança, registre assim, sem apresentá-la como comprovação técnica.','Se houver alterações anteriores, procure documentá-las. O que está instalado pode exigir uma avaliação específica, e a ficha original do modelo não resolve todas as dúvidas.'),
      section('Respeite os recortes de aplicação','O KIT10011 aparece para amortecedores dianteiro e traseiro da D20 até 1992. O KIT10086 menciona aplicação a partir de 1993. Já o KIT10012 tem descrição para coxins de cabine D40/D20. '+ref('catalog')+'.','Esses exemplos mostram por que o ano e o conjunto precisam acompanhar a indicação. Não se deve tratar os códigos como equivalentes nem ampliar uma faixa por parecer próxima à do veículo.'),
      section('Preservar também é poder explicar o serviço','Depois de uma intervenção, registre o que foi avaliado e o que foi efetivamente utilizado. Isso ajuda o próximo profissional e mantém o histórico compreensível para quem acompanha o carro. A memória afetiva ganha um apoio concreto.','Que história sua D20 guarda? Conte à RochaPro e, para uma manutenção indicada, consulte os kits abaixo com ano, versão e posição da peça.')
    ],['KIT10011','KIT10086','KIT10012'],['d20Culture','catalog']),
  entry('f1000','f1000-antes-depois-1992-pecas','F1000: história de garagem, atenção ao ano e às peças',
    'Na F1000, memória e manutenção caminham juntas. Confira como organizar referências e respeitar os períodos dos kits disponíveis.', 'Histórias de garagem',
    'Quando uma F1000 permanece por muitos anos com a mesma família, as histórias se acumulam mais rápido do que os documentos de manutenção. Organizar esses registros ajuda a preservar o veículo e evita que a próxima consulta de peças dependa apenas da memória.',[
      section('Uma picape presente na cultura de antigos','A Casa de Metal registrou a F1000 entre os modelos expostos no encontro O Barão, em março de 2025. O evento era multimarcas; sua presença não permite calcular o alcance de uma comunidade exclusiva da picape. '+ref('f1000Culture')+'.','A oportunidade de conversa está na conservação, nos usos que mudaram com o tempo e nas histórias familiares. Uma foto antiga pode ser o começo de um relato, desde que data e contexto sejam preservados quando conhecidos.'),
      section('Reconstrua o histórico sem inventar o que falta','Separe comprovantes, referências de peças e informações transmitidas por antigos proprietários. Registre as lacunas para que a oficina saiba o que ainda precisa avaliar. A falta de documento não comprova defeito, mas pede cuidado com conclusões.','Se houve alteração de conjunto, informe isso antes da cotação. A identificação original do veículo não garante que a aplicação cadastrada corresponda a tudo o que está instalado.'),
      section('Observe a mudança de período nas descrições','O KIT10025 aparece para tensor de F100/F1000 até 1992. O KIT10271 traz aplicação de amortecedor dianteiro de 1993 a 1998. O KIT10019 se refere a coxins de cabine da F1000 até 1992. '+ref('catalog')+'.','Ano e função são informações inseparáveis nessa leitura. Não escolha um kit apenas porque contém F1000 no título, nem interprete os códigos como uma lista de trocas recomendadas.'),
      section('Deixe a próxima consulta mais simples','Depois do diagnóstico, mantenha código, descrição, quantidade e posição na mesma cotação. Ao concluir o serviço, guarde a referência utilizada junto da ordem de serviço. Assim, o histórico continua útil mesmo quando muda quem cuida do carro.','Está conservando uma F1000? Compartilhe sua história com a RochaPro e confira os kits abaixo para consultar uma necessidade identificada, com confirmação de aplicação e disponibilidade.')
    ],['KIT10025','KIT10271','KIT10019'],['f1000Culture','catalog']),
];
